require_once __DIR__.'/../includes/bootstrap.php';require_role('Faculty');check_csrf();$u=current_user();$f=db()->prepare('SELECT id FROM faculty WHERE user_id=?');$f->execute([$u['id']]);$fid=(int)$f->fetchColumn();if($_SERVER['REQUEST_METHOD']==='POST')try{$a=FileService::save($_FILES['file']??null,'materials',['pdf'=>['application/pdf'],'doc'=>['application/msword'],'docx'=>['application/vnd.openxmlformats-officedocument.wordprocessingml.document'],'ppt'=>['application/vnd.ms-powerpoint'],'pptx'=>['application/vnd.openxmlformats-officedocument.presentationml.presentation'],'zip'=>['application/zip'],'jpg'=>['image/jpeg'],'jpeg'=>['image/jpeg'],'png'=>['image/png']]);$q=db()->prepare('INSERT INTO study_materials(subject_id,faculty_id,title,file_path,mime_type,file_size) VALUES(?,?,?,?,?,?)');$q->execute([(int)$_POST['subject_id'],$fid,trim($_POST['title']),$a['path'],$a['mime'],$a['size']]);AuditService::log('UPLOAD','materials',(int)db()->lastInsertId(),'Study material');$_SESSION['flash']=['success','Material uploaded'];}catch(Throwable $e){$_SESSION['flash']=['danger',$e->getMessage()];}redirect('materials.php');$subs=db()->query('SELECT id,code,name FROM subjects ORDER BY name')->fetchAll();page_top('Study Material Vault');flash();?><div class='card p-4'><form method='post' enctype='multipart/form-data' class='row g-3'><input type='hidden' name='csrf' value='<?=e(csrf_token())?>'><div class='col-md-6'><label>Subject</label><select name='subject_id' class='form-select'><?php foreach($subs as $s):?><option value='<?=e($s['id'])?>'><?=e($s['code'].' · '.$s['name'])?></option><?php endforeach;?></select></div><div class='col-md-6'><label>Title</label><input name='title' class='form-control' required></div><div class='col-12'><label>File</label><input type='file' name='file' class='form-control' required></div><button class='btn btn-primary col-md-2'>Upload</button></form></div><?php page_bottom();